gcRm(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u062d\u0633\u0627\u0628 \u0628\u0627\u0646\u06a9\u06cc"},
gcRn(){return"\u0686\u06a9"},
gcRo(){return"\u0627\u0646\u062a\u062e\u0627\u0628 \u06cc\u0627 \u062b\u0628\u062a \u0686\u06a9 \u062f\u0631\u06cc\u0627\u0641\u062a\u06cc"},
