gcRc(){return"\u062d\u0630\u0641"},
gcRa(){return"\u0645\u0634\u062a\u0631\u06cc \u0646\u0627\u0634\u0646\u0627\u0633"},
gbAo(){return"\u062a\u0646\u0638\u06cc\u0645\u0627\u062a Redis Cache"},
