gcAZ(){return"\u0633\u0627\u0639\u0627\u062a \u062b\u0627\u0628\u062a \u0631\u0648\u0632\u0627\u0646\u0647"},
gcAT(){return"\u0628\u0627\u0632\u0647"},
cAQ(a){return"\u0647\u0631 "+a+" \u0633\u0627\u0639\u062a"},
