gcB9(){return"\u0645\u0642\u062f\u0627\u0631"},
gcBf(){return"\u0646\u0631\u062e \u0645\u0631\u062c\u0639"},
gcAR(){return"\u0646\u0631\u062e \u0646\u0647\u0627\u06cc\u06cc \u067e\u0633 \u0627\u0632 \u0622\u0641\u0633\u062a"},
gcBe(){return"\u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0632\u0646\u062f\u0647 \u0627\u0632 \u0627\u0633\u0646\u067e\u200c\u0634\u0627\u062a \u0645\u0631\u06a9\u0632\u06cc \u0628\u0627 \u067e\u06cc\u0634\u200c\u0646\u0648\u06cc\u0633 \u0641\u0639\u0644\u06cc."},
